WITH srp_deduped AS ( SELECT DISTINCT s.mri_session_id, s.route_id, s.rb_user_id, s.user_type, s.os, s.channel, s.src_id, s.dest_id, -- CASE WHEN (s.mri_session_id, s.route_id) IN (SELECT DISTINCT mri_session_id, route_id FROM offer_tuple) THEN 'DBS Tuple' ELSE 'non-DBS Tuple' END AS tuple_type, CASE WHEN __time >= TIMESTAMP '2025-12-31 18:30:00' AND __time < TIMESTAMP '2026-01-06 18:30:00' THEN 'Pre DBS' WHEN __time >= TIMESTAMP '2026-01-06 18:30:00' AND __time < TIMESTAMP '2026-01-18 18:30:00' THEN 'Post DBS' ELSE 'Others' END AS time_period FROM "user_interaction"."search_route_details" s -- LEFT JOIN short_routes sr ON s.src_id = sr.src_id AND s.dest_id = sr.dest_id WHERE s.__time >= TIMESTAMP '2025-12-31 18:30:00' AND s.__time < TIMESTAMP '2026-01-18 18:30:00' AND s.channel IN ('MOBILE_APP', 'MOBILE_WEB', 'WEB_DIRECT') AND s.group_id IN (10283, 16081, 6392, 15447, 8065, 15129, 7115, 10244, 10823, 15130, 11060, 15499, 11044, 3030, 15443, 16124, 16227, 2020, 16374, 16426, 16580, 16647, 16777, 17012, 16884, 4040, 17137, 17101, 17889, 18115, 18101, 18237, 18491, 19393, 19502, 22837, 22875, 22878, 24978, 25187, 25946, 27000, 26936, 27455, 28011, 29176, 29479, 29391, 29392, 32000, 32272, 32245, 34300, 34400, 33740, 35303, 35268) -- AND s.os = 'Android' AND s.country = 'IND' -- GROUP BY 1,2,3,4,5,6,7,8,9 ), offer_tuple AS ( SELECT DISTINCT mri_session_id, route_id, rb_user_id, src_id, dest_id FROM "user_interaction"."search_route_details" WHERE __time >= TIMESTAMP '2025-12-06 18:30:00' AND __time < TIMESTAMP '2026-01-18 18:30:00' AND channel IN ('MOBILE_APP', 'MOBILE_WEB', 'WEB_DIRECT') AND campaign_id LIKE '%MULSTL_DBIND%' AND country = 'IND' ), confirm_deduped AS ( SELECT mri_session_id, route_id, CASE WHEN operator_id IN (10283, 16081, 6392, 15447, 8065, 15129, 7115, 10244, 10823, 15130, 11060, 15499, 11044, 3030, 15443, 16124, 16227, 2020, 16374, 16426, 16580, 16647, 16777, 17012, 16884, 4040, 17137, 17101, 17889, 18115, 18101, 18237, 18491, 19393, 19502, 22837, 22875, 22878, 24978, 25187, 25946, 27000, 26936, 27455, 28011, 29176, 29479, 29391, 29392, 32000, 32272, 32245, 34300, 34400, 33740, 35303, 35268) THEN 'RTC' ELSE 'Pvt' END AS rtc_pvt, MAX(rb_user_id) as rb_user_id, COUNT(DISTINCT tin) as tin_count FROM "user_interaction"."confirm_order_details" WHERE __time >= TIMESTAMP '2025-12-31 18:30:00' AND __time < TIMESTAMP '2026-01-18 18:30:00' -- AND os = 'Android' AND country = 'IND' AND status = 200 AND tin IS NOT NULL AND tin NOT IN ('', 'null') GROUP BY 1,2,3 ) SELECT s.time_period, CASE WHEN (s.src_id, s.dest_id) IN (SELECT DISTINCT src_id, dest_id FROM offer_tuple) THEN 'DBS Routes' ELSE 'non-DBS routes' END AS route_type, CASE WHEN s.os IS NULL THEN s.channel ELSE s.os END AS saleschannel, COUNT(DISTINCT s.mri_session_id) banner_traffic, COUNT(DISTINCT c.mri_session_id) overall_confirms_off_banner_sessions, COUNT(DISTINCT CASE WHEN c.rtc_pvt = 'RTC' THEN c.mri_session_id END) AS confirmed_on_rtc, COUNT(DISTINCT CASE WHEN c.rtc_pvt = 'Pvt' THEN c.mri_session_id END) AS confirmed_on_pvt, COUNT(DISTINCT CASE WHEN (c.mri_session_id, c.route_id) IN (SELECT DISTINCT mri_session_id, route_id FROM offer_tuple) THEN c.mri_session_id END) AS dbs_confirmed_sessions, COUNT(DISTINCT CASE WHEN c.rtc_pvt = 'Pvt' AND (c.mri_session_id, c.route_id) NOT IN (SELECT DISTINCT mri_session_id, route_id FROM offer_tuple) THEN c.mri_session_id END) AS non_dbs_pvt_confirmed_sessions FROM srp_deduped s LEFT JOIN confirm_deduped c ON s.mri_session_id = c.mri_session_id GROUP BY 1, 2, 3
